// Synthetic benchmark runner for reqmd.
//
// Reproduces the benchmark documented on the Hugo site's /benchmarks/ page:
//
//  1. Baseline: the real bundled spec/ tree (249 requirements, 6 doc dirs).
//  2. Scaling: a synthetic corpus generated by reqmd-bench-gen at four
//     scales (71k, 180k, 360k, 720k requirements), each 36 documents.
//
// Each command at each scale is measured -runs times (default 5); the median
// wall time is reported. Peak RSS is the max across all runs.
//
// Output: JSON report on stdout (and -out file) containing hardware metadata,
// the baseline measurement, and the scaling measurements.
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"slices"
	"strings"
	"sync/atomic"
	"time"
)

type scale struct {
	Label      string `json:"label"`
	Copies     int    `json:"copies"`
	ReqsPerDoc int    `json:"reqs_per_doc"`
}

type measurement struct {
	Scale      string  `json:"scale"`
	Command    string  `json:"command"`
	AllWallMs  []int64 `json:"all_wall_ms,omitempty"`
	Copies     int     `json:"copies"`
	ReqsPerDoc int     `json:"reqs_per_doc,omitempty"`
	TotalReqs  int     `json:"total_reqs"`
	Docs       int     `json:"docs"`
	WallMs     int64   `json:"wall_ms"`
	PeakRSSKB  int64   `json:"peak_rss_kb"`
	Runs       int     `json:"runs"`
	ExitCode   int     `json:"exit_code"`
}

type hardware struct {
	GoVersion  string `json:"go_version"`
	OS         string `json:"os"`
	Arch       string `json:"arch"`
	CPUModel   string `json:"cpu_model"`
	CPUMHz     string `json:"cpu_mhz,omitempty"`
	Kernel     string `json:"kernel,omitempty"`
	Hostname   string `json:"hostname,omitempty"`
	NumCPU     int    `json:"num_cpu"`
	MemTotalKB int64  `json:"mem_total_kb,omitempty"`
}

type report struct {
	Timestamp string        `json:"timestamp"`
	Baseline  []measurement `json:"baseline"`
	Scales    []scale       `json:"scales"`
	Scaling   []measurement `json:"scaling"`
	Hardware  hardware      `json:"hardware"`
	DurationS float64       `json:"duration_s"`
}

var peakRSS atomic.Int64

func main() {
	src := flag.String("src", "", "source spec dir (the real one, e.g. spec/)")
	gen := flag.String("gen", "", "path to reqmd-bench-gen binary")
	reqmd := flag.String("reqmd", "", "path to reqmd binary")
	out := flag.String("out", "", "output JSON file (also written to stdout)")
	work := flag.String("work", "/tmp/reqmd-bench", "scratch directory")
	scalesFlag := flag.String("scales", "2000,5000,10000,20000", "comma-separated reqs/doc targets")
	runs := flag.Int("runs", 5, "number of runs per measurement (median wall time reported)")
	skipBaseline := flag.Bool("skip-baseline", false, "skip the real-spec baseline measurement")
	skipScaling := flag.Bool("skip-scaling", false, "skip the synthetic scaling measurements")
	flagVerbose = flag.Bool("verbose", false, "include all per-run wall times in output")
	flag.Parse()

	if *src == "" || *gen == "" || *reqmd == "" {
		fmt.Fprintln(os.Stderr, "usage: -src <spec> -gen <bench-gen> -reqmd <reqmd> [-out file.json] [-work dir] [-scales 2000,...] [-runs N]")
		os.Exit(2)
	}

	startTime := time.Now()
	hw := collectHardware()

	var reqsPerDoc []int
	for s := range strings.SplitSeq(*scalesFlag, ",") {
		var n int
		fmt.Sscanf(strings.TrimSpace(s), "%d", &n)
		if n > 0 {
			reqsPerDoc = append(reqsPerDoc, n)
		}
	}
	if len(reqsPerDoc) == 0 {
		reqsPerDoc = []int{2000, 5000, 10000, 20000}
	}

	scales := make([]scale, len(reqsPerDoc))
	for i, n := range reqsPerDoc {
		scales[i] = scale{
			Label:      fmt.Sprintf("%dk reqs/doc", n/1000),
			Copies:     6, // 6 × spec doc dirs = 36 documents
			ReqsPerDoc: n,
		}
	}

	var baseline []measurement
	var scaling []measurement

	// --- Baseline: the real spec tree ---
	if !*skipBaseline {
		fmt.Fprintf(os.Stderr, "\n=== Baseline: real spec tree (%s) ===\n", *src)
		baseReqs, _ := countReqs(*src)
		baseDirs := countDirs(*src)
		fmt.Fprintf(os.Stderr, "    %d requirements, %d doc dirs\n", baseReqs, baseDirs)

		cmds := benchCommands(*src, filepath.Join(*work, "baseline-html"))
		for _, c := range cmds {
			m := measureN(*reqmd, c.name, "baseline", 0, 0, baseReqs, baseDirs, c.args, *runs)
			baseline = append(baseline, m)
			fmt.Fprintf(os.Stderr, "    %-15s %6dms (median of %d)  peak=%5dMB  exit=%d\n",
				c.name, m.WallMs, m.Runs, m.PeakRSSKB/1024, m.ExitCode)
		}
	}

	// --- Scaling: synthetic corpora ---
	if !*skipScaling {
		os.RemoveAll(*work)
		if err := os.MkdirAll(*work, 0o755); err != nil {
			panic(err)
		}

		for _, s := range scales {
			fmt.Fprintf(os.Stderr, "\n>>> scale %s: %d copies, %d reqs/doc\n", s.Label, s.Copies, s.ReqsPerDoc)
			root := filepath.Join(*work, fmt.Sprintf("reqs%d", s.ReqsPerDoc))
			if err := os.MkdirAll(root, 0o755); err != nil {
				panic(err)
			}
			genArgs := []string{"-src", *src, "-dst", root, "-copies", fmt.Sprintf("%d", s.Copies), "-reqsperdoc", fmt.Sprintf("%d", s.ReqsPerDoc)}
			genCmd := exec.Command(*gen, genArgs...)
			if genOut, err := genCmd.CombinedOutput(); err != nil {
				fmt.Fprintf(os.Stderr, "gen error: %v\n%s\n", err, genOut)
				panic(err)
			}
			totalReqs, _ := countReqs(root)
			docs := countDirs(root)
			fmt.Fprintf(os.Stderr, "    -> %d requirements, %d doc dirs\n", totalReqs, docs)

			cmds := benchCommands(root, filepath.Join(*work, fmt.Sprintf("html-%d", s.ReqsPerDoc)))
			for _, c := range cmds {
				m := measureN(*reqmd, c.name, s.Label, s.Copies, s.ReqsPerDoc, totalReqs, docs, c.args, *runs)
				scaling = append(scaling, m)
				fmt.Fprintf(os.Stderr, "    %-15s %6dms (median of %d)  peak=%5dMB  %8.0f req/s  exit=%d\n",
					c.name, m.WallMs, m.Runs, m.PeakRSSKB/1024, float64(totalReqs)/(float64(m.WallMs)/1000.0), m.ExitCode)
			}
		}
	}

	rep := report{
		Timestamp: time.Now().UTC().Format(time.RFC3339),
		Hardware:  hw,
		Baseline:  baseline,
		Scales:    scales,
		Scaling:   scaling,
		DurationS: time.Since(startTime).Seconds(),
	}

	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	if err := enc.Encode(rep); err != nil {
		panic(err)
	}
	if *out != "" {
		f, err := os.Create(*out)
		if err != nil {
			panic(err)
		}
		defer f.Close()
		enc := json.NewEncoder(f)
		enc.SetIndent("", "  ")
		enc.Encode(rep)
	}
}

type cmd struct {
	name string
	args []string
}

func benchCommands(root, htmlOut string) []cmd {
	return []cmd{
		{"check", []string{"check", root}},
		{"check --json", []string{"check", "--json", root}},
		{"ls", []string{"ls", root}},
		{"stats", []string{"stats", root}},
		{"export html", []string{"export", "html", root, "-o", htmlOut}},
	}
}

// measureN runs the command `runs` times and returns a measurement with the
// median wall time and the peak RSS across all runs.
func measureN(reqmdBin, cmdName, scaleLabel string, copies, reqsPerDoc, totalReqs, docs int, args []string, runs int) measurement {
	m := measurement{
		Scale:      scaleLabel,
		Copies:     copies,
		ReqsPerDoc: reqsPerDoc,
		TotalReqs:  totalReqs,
		Docs:       docs,
		Command:    cmdName,
		Runs:       runs,
	}
	var allWall []int64
	var maxRSS int64
	for range runs {
		wm, rss, ec := measureOnce(reqmdBin, args)
		allWall = append(allWall, wm)
		if rss > maxRSS {
			maxRSS = rss
		}
		m.ExitCode = ec
	}
	slices.Sort(allWall)
	m.WallMs = allWall[len(allWall)/2] // median
	m.PeakRSSKB = maxRSS
	if *flagVerbose {
		m.AllWallMs = allWall
	}
	return m
}

var flagVerbose *bool

func measureOnce(reqmdBin string, args []string) (wallMs int64, peakRSSKB int64, exitCode int) {
	c := exec.Command(reqmdBin, args...)
	c.Stdout = nil
	c.Stderr = nil
	start := time.Now()
	if err := c.Start(); err != nil {
		return 0, 0, -1
	}
	peakRSS.Store(0)
	doneCh := make(chan struct{})
	go sampleRSS(c.Process.Pid, doneCh)
	_ = c.Wait()
	elapsed := time.Since(start)
	close(doneCh)
	wallMs = elapsed.Milliseconds()
	peakRSSKB = peakRSS.Load()
	if c.ProcessState != nil {
		exitCode = c.ProcessState.ExitCode()
	}
	return
}

func countReqs(root string) (int, error) {
	count := 0
	err := filepath.Walk(root, func(p string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() {
			return nil
		}
		if !strings.HasSuffix(p, ".md") {
			return nil
		}
		b, err := os.ReadFile(p)
		if err != nil {
			return fmt.Errorf("reading %s: %w", p, err)
		}
		count += strings.Count(string(b), "\n## ")
		return nil
	})
	if err != nil {
		return count, fmt.Errorf("walking %s: %w", root, err)
	}
	return count, nil
}

func countDirs(root string) int {
	count := 0
	filepath.Walk(root, func(p string, info os.FileInfo, err error) error {
		if err == nil && info.IsDir() {
			count++
		}
		return nil
	})
	return count
}

func sampleRSS(pid int, done <-chan struct{}) {
	tick := time.NewTicker(10 * time.Millisecond)
	defer tick.Stop()
	for {
		select {
		case <-done:
			return
		case <-tick.C:
			kb := readRSSKB(pid)
			if kb > peakRSS.Load() {
				peakRSS.Store(kb)
			}
		}
	}
}

func readRSSKB(pid int) int64 {
	data, err := os.ReadFile(fmt.Sprintf("/proc/%d/status", pid))
	if err != nil {
		return 0
	}
	for line := range strings.SplitSeq(string(data), "\n") {
		if strings.HasPrefix(line, "VmRSS:") {
			fields := strings.Fields(line)
			if len(fields) >= 2 {
				var kb int64
				if _, err := fmt.Sscanf(fields[1], "%d", &kb); err == nil {
					return kb
				}
			}
		}
	}
	return 0
}

// collectHardware gathers CPU, OS, and runtime metadata for reproducibility.
func collectHardware() hardware {
	hw := hardware{
		GoVersion: runtime.Version(),
		OS:        runtime.GOOS,
		Arch:      runtime.GOARCH,
		NumCPU:    runtime.NumCPU(),
	}

	if hostname, err := os.Hostname(); err == nil {
		hw.Hostname = hostname
	}

	// Linux /proc/cpuinfo and /proc/meminfo
	if data, err := os.ReadFile("/proc/cpuinfo"); err == nil {
		for line := range strings.SplitSeq(string(data), "\n") {
			if strings.HasPrefix(line, "model name") {
				fields := strings.SplitN(line, ":", 2)
				if len(fields) == 2 {
					hw.CPUModel = strings.TrimSpace(fields[1])
				}
			}
			if strings.HasPrefix(line, "cpu MHz") && hw.CPUMHz == "" {
				fields := strings.SplitN(line, ":", 2)
				if len(fields) == 2 {
					hw.CPUMHz = strings.TrimSpace(fields[1])
				}
			}
		}
	}

	if data, err := os.ReadFile("/proc/meminfo"); err == nil {
		for line := range strings.SplitSeq(string(data), "\n") {
			if strings.HasPrefix(line, "MemTotal:") {
				fields := strings.Fields(line)
				if len(fields) >= 2 {
					fmt.Sscanf(fields[1], "%d", &hw.MemTotalKB)
				}
			}
		}
	}

	// uname -r for kernel version
	if out, err := exec.Command("uname", "-r").Output(); err == nil {
		hw.Kernel = strings.TrimSpace(string(out))
	}

	return hw
}
